    ctx.restore();
  }

  function drawHud(game) {
    const { player, mission, message, messageTimer } = game;
    ctx.textBaseline = 'alphabetic';

    // Top-left panel: money, health, wanted stars.
    ctx.fillStyle = C.hudPanel;
