    for (let i = 0; i < 5; i++) stars += i < player.wanted ? '★' : '☆';
    ctx.fillStyle = player.wanted > 0 ? C.hudGold : 'rgba(255,255,255,0.45)';
    ctx.fillText(stars, 28, 100);

    // Mission panel, top centre.
    if (mission) {
      const panelW = 460;
      ctx.fillStyle = C.hudPanel;
