      ctx.fillStyle = C.hudGold;
      ctx.font = 'bold 17px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(mission.name, VIEW_W / 2, 38);
      ctx.fillStyle = C.hudText;
      ctx.font = '14px sans-serif';
